namespace codane {Json Event::json()const{Json::object o{{"schema_version",1},{"sequence",double(sequence)},{"timestamp",timestamp},{"run_id",run_id},{"event_type",event_type},{"payload",payload}};if(!node_id.empty())o["node_id"]=node_id;return o;}Journal::Journal(std::filesystem::path p):path(std::move(p)){std::filesystem::create_directories(path.parent_path());for(auto&e:replay())next=std::max(next,e.sequence+1);}void Journal::append(const std::string&t,const RunId&r,const std::string&n,const Json&p,const std::string&){std::ofstream f(path,std::ios::app);if(!f)throw std::runtime_error("cannot open journal");Event e{next++,std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count()),r,t,n,p};f<<e.json().dump()<<'\n';f.flush();int fd=open(path.c_str(),O_WRONLY);if(fd>=0){fsync(fd);close(fd);}}std::vector<Event> Journal::replay()const{std::vector<Event>v;std::ifstream f(path);std::string l;uint64_t prev=0;while(std::getline(f,l)){if(l.empty())continue;Json j;try{j=Json::parse(l);}catch(...){throw std::runtime_error("malformed journal: "+path.string());}Event e{(uint64_t)j.at("sequence").number(),j.at("timestamp").str(),j.at("run_id").str(),j.at("event_type").str(),j.has("node_id")?j.at("node_id").str():"",j.at("payload")};if(e.sequence<=prev)throw std::runtime_error("journal sequence is not increasing");prev=e.sequence;v.push_back(e);}return v;}void atomic_write(const std::filesystem::path&p,const std::string&s){auto t=p; t+=".tmp";{std::ofstream f(t);f<<s;f.flush();}int fd=open(t.c_str(),O_WRONLY);if(fd>=0){fsync(fd);close(fd);}std::filesystem::rename(t,p);}}
